.empty-state {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  width: 100%;
  max-width: 28rem;
  margin: 0 auto;
  padding: 2.5rem 2rem;
  text-align: center;
  background-color: var(--empty-state-surface);
  border: 1px solid var(--empty-state-border);
  border-radius: 1rem;
  font-family: inherit;
}

.empty-state__title {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.3;
  color: var(--empty-state-title);
}

.empty-state__message {
  margin: 0;
  font-size: 0.95rem;
  line-height: 1.55;
  color: var(--empty-state-text);
}

.empty-state__action {
  margin-top: 0.5rem;
  min-height: 2.75rem;
  padding: 0.6rem 1.4rem;
  font: inherit;
  font-weight: 600;
  color: var(--empty-state-accent-text);
  background-color: var(--empty-state-accent);
  border: 1px solid transparent;
  border-radius: 999px;
  cursor: pointer;
  transition: background-color 150ms ease;
}

.empty-state__action:hover {
  background-color: var(--empty-state-accent-hover);
}

.empty-state__action:active {
  filter: brightness(0.95);
}

.empty-state__action:focus {
  outline: none;
}

.empty-state__action:focus-visible {
  outline: 3px solid var(--empty-state-focus);
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  .empty-state__action {
    transition: none;
  }
}
